import numpy as np
from scipy.spatial.distance import cdist
l=open('initial.xyz').readlines();el=np.array([s.split()[0] for s in l[2:]]);p=np.array([list(map(float,s.split()[1:])) for s in l[2:]])
# rotate all NHC atoms around respective Ir-C vector (approx ±y)
for angle in [65,80,90]:
 pp=p.copy();rad=np.deg2rad(angle);R=np.array([[np.cos(rad),0,-np.sin(rad)],[0,1,0],[np.sin(rad),0,np.cos(rad)]])
 pp[1:131]=pp[1:131]@R
 print('\nangle',angle)
 for i,j in [(131,133),(132,144)]:
  group=list(range(j,j+11)); sub=cdist(pp[group],pp[1:131]);pairs=sorted([(round(sub[u,v],2),group[u],v+1) for u in range(6) for v in range(130) if el[v+1]!='H']);print(i,'phenyl vs Dipp',pairs[:8]);
  closest=sorted([(round(np.linalg.norm(pp[i]-pp[jj]),2),jj) for jj in range(1,131) if el[jj]!='H'])[:5];print('Zn',closest)
  b=cdist(pp[1:66],pp[66:131]); ind=np.unravel_index(np.argmin(b),b.shape);print('upper lower closest overall',round(b[ind],2),ind)
 if angle==90:
  with open('rot90.xyz','w') as out:
   out.writelines(l[:2]);
   for e,v in zip(el,pp):out.write(f'{e} {v[0]:.9f} {v[1]:.9f} {v[2]:.9f}\n')
